  1046  UA_StatusCode
  1047  UA_Array_copy(const void *src, size_t size,
  1048                void **dst, const UA_DataType *type) {
  1049      if(size == 0) {
  1050          if(src == NULL)
  1051              *dst = NULL;
  1052          else
  1053              *dst= UA_EMPTY_ARRAY_SENTINEL;
  1054          return UA_STATUSCODE_GOOD;
  1055      }
  1056
  1057      if(!type)
  1058          return UA_STATUSCODE_BADINTERNALERROR;
  1059
  1060      /* calloc, so we don't have to check retval in every iteration of copying */
  1061      *dst = UA_calloc(size, type->memSize);
  1062      if(!*dst)
  1063          return UA_STATUSCODE_BADOUTOFMEMORY;
  1064
  1065      if(type->pointerFree) {
  1066          memcpy(*dst, src, type->memSize * size);
  1067          return UA_STATUSCODE_GOOD;
  1068      }
  1069
  1070      uintptr_t ptrs = (uintptr_t)src;
  1071      uintptr_t ptrd = (uintptr_t)*dst;
  1072      UA_StatusCode retval = UA_STATUSCODE_GOOD;
  1073      for(size_t i = 0; i < size; ++i) {
  1074          retval |= UA_copy((void*)ptrs, (void*)ptrd, type);
  1075          ptrs += type->memSize;
  1076          ptrd += type->memSize;
  1077      }
  1078      if(retval != UA_STATUSCODE_GOOD) {
  1079          UA_Array_delete(*dst, size, type);
  1080          *dst = NULL;
  1081      }
  1082      return retval;
  1083  }
