  1086  UA_Array_delete(void *p, size_t size, const UA_DataType *type) {
  1087      if(!type->pointerFree) {
  1088          uintptr_t ptr = (uintptr_t)p;
  1089          for(size_t i = 0; i < size; ++i) {
  1090              UA_clear((void*)ptr, type);
  1091              ptr += type->memSize;
  1092          }
  1093      }
  1094      UA_free((void*)((uintptr_t)p & ~(uintptr_t)UA_EMPTY_ARRAY_SENTINEL));
