  1098  UA_DataType_isNumeric(const UA_DataType *type) {
  1099      /* All data types between UA_TYPES_BOOLEAN and UA_TYPES_DOUBLE are numeric */
  1100      for(size_t i = UA_TYPES_BOOLEAN; i <= UA_TYPES_DOUBLE; ++i)
  1101          if(&UA_TYPES[i] == type)
  1102              return true;
  1103      return false;
