  1110  static size_t
  1111  readDimension(UA_Byte *buf, size_t buflen, UA_NumericRangeDimension *dim) {
  1112      size_t progress = UA_readNumber(buf, buflen, &dim->min);
  1113      if(progress == 0)
  1114          return 0;
  1115      if(buflen <= progress + 1 || buf[progress] != ':') {
  1116          dim->max = dim->min;
  1117          return progress;
  1118      }
  1119
  1120      ++progress;
  1121      size_t progress2 = UA_readNumber(&buf[progress], buflen - progress, &dim->max);
  1122      if(progress2 == 0)
  1123          return 0;
  1124
  1125      /* invalid range */
  1126      if(dim->min >= dim->max)
  1127          return 0;
  1128
  1129      return progress + progress2;
  1130  }
