  1132  UA_StatusCode
  1133  UA_NumericRange_parseFromString(UA_NumericRange *range, const UA_String *str) {
  1134      size_t idx = 0;
  1135      size_t dimensionsMax = 0;
  1135      size_t dimensionsMax = 0;
  1136      UA_NumericRangeDimension *dimensions = NULL;
  1137      UA_StatusCode retval = UA_STATUSCODE_GOOD;
  1138      size_t offset = 0;
  1139      while(true) {
  1140          /* alloc dimensions */
  1141          if(idx >= dimensionsMax) {
  1142              UA_NumericRangeDimension *newds;
  1143              size_t newdssize = sizeof(UA_NumericRangeDimension) * (dimensionsMax + 2);
  1144              newds = (UA_NumericRangeDimension*)UA_realloc(dimensions, newdssize);
  1145              if(!newds) {
  1146                  retval = UA_STATUSCODE_BADOUTOFMEMORY;
  1147                  break;
  1148              }
  1149              dimensions = newds;
  1150              dimensionsMax = dimensionsMax + 2;
  1151          }
  1152
  1153          /* read the dimension */
  1154          size_t progress = readDimension(&str->data[offset], str->length - offset,
  1155                                          &dimensions[idx]);
  1156          if(progress == 0) {
  1157              retval = UA_STATUSCODE_BADINDEXRANGEINVALID;
  1158              break;
  1159          }
  1160          offset += progress;
  1161          ++idx;
  1162
  1163          /* loop into the next dimension */
  1164          if(offset >= str->length)
  1165              break;
  1166
  1167          if(str->data[offset] != ',') {
  1168              retval = UA_STATUSCODE_BADINDEXRANGEINVALID;
  1169              break;
  1170          }
  1171          ++offset;
  1172      }
  1173
  1174      if(retval == UA_STATUSCODE_GOOD && idx > 0) {
  1175          range->dimensions = dimensions;
  1176          range->dimensionsSize = idx;
  1177      } else
  1178          UA_free(dimensions);
  1179
  1180      return retval;
  1181  }
